const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hongKong = ee.Geometry.Polygon([
    [113.8, 22.1],
    [114.5, 22.1],
    [114.5, 22.6],
    [113.8, 22.6],
    [113.8, 22.1]
  ]);

  const period1_start = '2020-02-10';
  const period1_end = '2020-02-25';
  const period2_start = '2020-04-20';
  const period2_end = '2020-05-12';

  // 2. Data Acquisition - Sentinel-5P NO2
  const no2_col = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const period1_col = no2_col.filterDate(period1_start, period1_end);
  const period2_col = no2_col.filterDate(period2_start, period2_end);

  const period1_size = period1_col.size().getInfo();
  const period2_size = period2_col.size().getInfo();

  console.log(`Period 1 (Feb 10-25) Images: ${period1_size}`);
  console.log(`Period 2 (Apr 20-May 12) Images: ${period2_size}`);

  // Check for empty collections
  if (period1_size === 0 || period2_size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create mean composites
  const period1_mean = period1_col.mean();
  const period2_mean = period2_col.mean();

  // Check valid pixels
  const count1 = period1_mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const count2 = period2_mean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Period 1 Valid Pixels: ${count1}`);
  console.log(`Period 2 Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NO2 values
  const mean1 = period1_mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const mean2 = period2_mean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: hongKong,
    scale: 1000,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  console.log(`Period 1 Mean NO2: ${mean1 ? mean1.toFixed(6) : 'null'}`);
  console.log(`Period 2 Mean NO2: ${mean2 ? mean2.toFixed(6) : 'null'}`);

  // Validation & Final Answer
  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log("<answer>C3</answer>");
  } else if (mean2 > mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
